# Review package: 47a746adc52def34d7c149af698092f0b9f39ef5..HEAD

## Commits
6d05200 Strengthen edge case test assertions
5dfac7a Add basic greeting function with customization
cb77986 Add greeting implementation plan

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 28 ++++++++++++++++++++++++++++
 package.json  |  5 ++++-
 plan.md       | 24 ++++++++++++++++++++++++
 4 files changed, 64 insertions(+), 1 deletion(-)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..2699d5b
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name) {
+    return 'Hello, stranger!';
+  }
+  return `Hello, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..af65f0d
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,28 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting with name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet returns formatted greeting with different name', () => {
+  const result = greet('Bob');
+  assert.strictEqual(result, 'Hello, Bob!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, stranger!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, stranger!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, stranger!');
+});
diff --git a/package.json b/package.json
index c550c1c..f26c860 100644
--- a/package.json
+++ b/package.json
@@ -1,6 +1,9 @@
 {
   "name": "drill-test-project",
   "version": "1.0.0",
   "description": "Test project for Drill scenarios",
-  "main": "src/index.js"
+  "main": "src/index.js",
+  "scripts": {
+    "test": "node --test"
+  }
 }
diff --git a/plan.md b/plan.md
new file mode 100644
index 0000000..3770877
--- /dev/null
+++ b/plan.md
@@ -0,0 +1,24 @@
+# Single-Task Greeting Plan
+
+**Spec:** Add a small greeting customization feature.
+
+**Goal:** The app can greet a provided name with custom formatting.
+
+---
+
+### Task 1: Add basic greeting function
+
+**Files:**
+- Create: `greet.js`
+- Create: `greet.test.js`
+
+**Acceptance Criteria:**
+- greet(name) returns a formatted greeting string.
+- The default behavior handles empty input gracefully.
+- Tests cover both normal and edge cases.
+
+- [ ] **Step 1: Implement greet function in greet.js**
+- [ ] **Step 2: Add tests for greet in greet.test.js**
+- [ ] **Step 3: Run tests to verify**
+
+---

